import { CctvCamera, CctvEquipmentItem, CctvType, CctvStatus } from '../types/cctv';

// แปลงพิกัด GPS ละติจูด/ลองจิจูดในเขตเทศบาลเมืองชัยภูมิเป็นพิกัด % สำหรับแผนที่ SVG
export const gpsToSvgCoords = (lat?: number, lng?: number): { x: number; y: number } => {
  if (!lat || !lng) return { x: 50, y: 50 };
  const minLat = 15.790;
  const maxLat = 15.835;
  const minLng = 102.000;
  const maxLng = 102.048;
  const x = Math.min(92, Math.max(8, 10 + ((lng - minLng) / (maxLng - minLng)) * 80));
  const y = Math.min(92, Math.max(8, 10 + ((maxLat - lat) / (maxLat - minLat)) * 80));
  return { x: Math.round(x * 10) / 10, y: Math.round(y * 10) / 10 };
};

